MULTI_QUERY_TOOL_NAMES = frozenset({
    "search_code", "journal_search", "search_papers", "search_arxiv", "search_within_paper",
})
# These five accept a query list; the contract is published on their `query`
# parameter (see _compact_published_tool_schemas), not appended to descriptions.
